
/* ============ Tanggal ============ */
(function(){
  const hari=["Minggu","Senin","Selasa","Rabu","Kamis","Jumat","Sabtu"];
  const bulan=["Januari","Februari","Maret","April","Mei","Juni","Juli","Agustus","September","Oktober","November","Desember"];
  const d=new Date();
  document.getElementById('tanggalHariIni').textContent = hari[d.getDay()]+", "+d.getDate()+" "+bulan[d.getMonth()]+" "+d.getFullYear();
})();

/* ============ Navigasi utama ============ */
const bottomNavViews=['beranda','galeri','alat','tentang'];
function switchView(name){
  document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));
  document.getElementById('view-'+name).classList.add('active');
  document.querySelectorAll('nav.bottom button').forEach(b=>b.classList.toggle('active', b.dataset.view===name));
  window.scrollTo({top:0,behavior:'smooth'});
}
function switchSub(view, sub){
  document.querySelectorAll('#view-'+view+' .subview').forEach(v=>v.classList.remove('active'));
  document.getElementById(view+'-'+sub).classList.add('active');
  document.querySelectorAll('#view-'+view+' .tabbtn').forEach(b=>b.classList.toggle('active', b.dataset.sub===sub));
}
function gotoTool(view, sub){
  switchView(view);
  switchSub(view, sub);
}

