/* Hitung tanggal Jumat terdekat berdasarkan tanggal perangkat pengguna:
   - Kalau hari ini kebetulan Jumat, pakai tanggal hari ini.
   - Kalau bukan, majukan ke Jumat berikutnya.
   Dipanggil ulang setiap kali halaman dibuka, jadi otomatis berpindah ke
   Jumat berikutnya begitu Jumat sebelumnya terlewat — tidak perlu edit manual. */
function hitungJumatTerdekat(){
  const now = new Date();
  const hariIni = now.getDay(); // 0=Minggu, 1=Senin, ... 5=Jumat, 6=Sabtu
  const selisihHari = (5 - hariIni + 7) % 7;
  const target = new Date(now.getFullYear(), now.getMonth(), now.getDate() + selisihHari);
  return target.getFullYear()+'-'+String(target.getMonth()+1).padStart(2,'0')+'-'+String(target.getDate()).padStart(2,'0');
}

