const kegiatanListEl=document.getElementById('kegiatanList');
let kegiatanFilterAktif='semua';
function renderKegiatan(){
  let data=[...kegiatanData];
  if(kegiatanFilterAktif==='mendatang') data=data.filter(k=>k.status==='Mendatang');
  if(kegiatanFilterAktif==='selesai') data=data.filter(k=>k.status==='Selesai');
  data.sort((a,b)=> new Date(a.tanggal||'9999-12-31') - new Date(b.tanggal||'9999-12-31'));
  kegiatanListEl.innerHTML='';
  if(data.length===0){ kegiatanListEl.innerHTML='<div class="empty-note">Belum ada kegiatan pada kategori ini.</div>'; return; }
  data.forEach(k=>{
    const el=document.createElement('div');
    el.className='item-card';
    const statusClass = k.status==='Mendatang' ? 'status-mendatang' : (k.status==='Selesai' ? 'status-selesai' : (String(k.status).indexOf('Coming')>-1 ? 'status-mendatang' : 'status-selesai'));
    el.innerHTML=`<div class="item-top">
        <div><div class="item-title">${k.nama}</div><div class="item-cat">${k.kategori}</div></div>
        <span class="status-pill ${statusClass}">${k.status}</span>
      </div>
      ${k.tanggal?('<div class="item-meta"><span>📅 '+formatTanggal(k.tanggal)+'</span>'+(k.lokasi?('<span>📍 '+k.lokasi+'</span>'):'')+'</div>') : '<div class="item-meta"><span>🔜 Coming Soon</span></div>'}
      <div class="item-desc">${k.deskripsi}</div>
      ${k.foto?'<div class="foto-flag">🖼️ Dokumentasi tersedia di Galeri</div>':''}`;
    kegiatanListEl.appendChild(el);
  });
}
function filterKegiatan(f){
  kegiatanFilterAktif=f;
  document.querySelectorAll('#kegiatanFilter .filter-chip').forEach(c=>c.classList.toggle('active', c.dataset.f===f));
  renderKegiatan();
}
function formatTanggal(iso){
  const bulan=["Jan","Feb","Mar","Apr","Mei","Jun","Jul","Agu","Sep","Okt","Nov","Des"];
  const d=new Date(iso+'T00:00:00');
  return d.getDate()+" "+bulan[d.getMonth()]+" "+d.getFullYear();
}
function kegiatanTerdekat(){
  const mendatang = kegiatanData.filter(k=>k.status==='Mendatang').sort((a,b)=>new Date(a.tanggal)-new Date(b.tanggal));
  return mendatang[0] || null;
}
function renderKegiatanBerikutnya(){
  const target=document.getElementById('kegiatanBerikutnya');
  const k=kegiatanTerdekat();
  if(!k){ target.innerHTML='<div class="empty-note">Belum ada kegiatan mendatang yang dijadwalkan.</div>'; return; }
  target.innerHTML=`<span class="mtag">${k.kategori}</span>
    <div class="mtitle">${k.nama}</div>
    <div class="msub">📅 ${formatTanggal(k.tanggal)} · 📍 ${k.lokasi}</div>`;
}
function renderMiniKegiatan(){
  const target=document.getElementById('miniKegiatan');
  const k=kegiatanTerdekat();
  if(!k){ target.innerHTML='<div class="msub">Belum ada kegiatan mendatang.</div>'; return; }
  target.innerHTML=`<div class="mtitle">${k.nama}</div><div class="msub">📅 ${formatTanggal(k.tanggal)} · 📍 ${k.lokasi}</div>`;
}
renderKegiatan();
renderKegiatanBerikutnya();
renderMiniKegiatan();

