const beritaData = [
  // Contoh format (hapus tanda komentar & isi data asli jika sudah ada berita resmi):
  // { id:1, judul:"Judul Berita", tanggal:"2026-09-01", kategori:"Kegiatan",
  //   ringkasan:"Ringkasan singkat berita…", isiLengkap:"Isi lengkap berita di sini." }
];
const beritaListEl=document.getElementById('beritaList');
const beritaListWrap=document.getElementById('beritaListWrap');
const beritaDetailWrap=document.getElementById('beritaDetailWrap');
function renderBerita(){
  beritaListEl.innerHTML='';
  if(beritaData.length===0){
    beritaListEl.innerHTML='<div class="empty-note">Belum ada berita. Berita akan segera ditambahkan.</div>';
    return;
  }
  beritaData.forEach(b=>{
    const el=document.createElement('div');
    el.className='item-card';
    el.style.cursor='pointer';
    el.onclick=()=>bukaBerita(b.id);
    el.innerHTML=`<div class="berita-thumb"><svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="1.8"><rect x="3.5" y="4.5" width="17" height="15" rx="2"/><path d="M7.5 8.5h5v4h-5zM7.5 15h9"/></svg></div>
      <div class="item-cat">${b.kategori}</div>
      <div class="item-title">${b.judul}</div>
      <div class="item-meta"><span>📅 ${formatTanggal(b.tanggal)}</span></div>
      <div class="item-desc">${b.ringkasan}</div>`;
    beritaListEl.appendChild(el);
  });
}
function bukaBerita(id){
  const b=beritaData.find(x=>x.id===id);
  if(!b) return;
  beritaListWrap.style.display='none';
  beritaDetailWrap.style.display='block';
  beritaDetailWrap.innerHTML=`<a class="back-link" onclick="tutupBerita()">← Kembali ke daftar berita</a>
    <div class="berita-thumb"><svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="1.8"><rect x="3.5" y="4.5" width="17" height="15" rx="2"/><path d="M7.5 8.5h5v4h-5zM7.5 15h9"/></svg></div>
    <div class="item-cat">${b.kategori}</div>
    <h2 style="font-size:19px;color:var(--dark);margin:4px 0 6px;">${b.judul}</h2>
    <div class="item-meta" style="margin-bottom:10px;"><span>📅 ${formatTanggal(b.tanggal)}</span></div>
    <div class="item-desc" style="font-size:13px;">${b.isiLengkap}</div>`;
}
function tutupBerita(){ beritaDetailWrap.style.display='none'; beritaListWrap.style.display='block'; }
renderBerita();

