/* ========================================
   AKSES ID DEWAN PASUKAN — MATERI HW
   Password = ID Dewan Pasukan masing-masing (sumber: anggotaData, sama
   dengan data yang dipakai ABSEN). ID Pembina tetap terpisah karena
   bukan bagian dari anggotaData.
   ======================================== */
const PEMBINA_ID = "HW-QBH-2627-P000";
function isDewanPasukanIDValid(input){
  const clean = (input||"").trim().toUpperCase();
  if(!clean) return false;
  if(clean===PEMBINA_ID) return true;
  return anggotaData.some(a=>a.id.toUpperCase()===clean);
}

/* Status buka/tutup PER MATERI (bukan status global) — direset terkunci
   lagi setiap kali materi tersebut ditutup, jadi harus masukkan ID lagi
   tiap dibuka ulang. */
const materiUnlocked = {};
let materiPendingIndex = null;
let materiPendingEl = null;

function bukaMateriIdModal(){
  document.getElementById('materiIdInput').value='';
  document.getElementById('materiIdError').hidden=true;
  document.getElementById('materiIdModal').classList.add('is-open');
  setTimeout(()=>{ const inp=document.getElementById('materiIdInput'); if(inp) inp.focus(); }, 50);
}
function tutupMateriIdModal(){
  document.getElementById('materiIdModal').classList.remove('is-open');
  materiPendingIndex=null; materiPendingEl=null;
}
function submitMateriId(){
  const val=document.getElementById('materiIdInput').value;
  if(isDewanPasukanIDValid(val)){
    const idx=materiPendingIndex, el=materiPendingEl;
    document.getElementById('materiIdModal').classList.remove('is-open');
    materiPendingIndex=null; materiPendingEl=null;
    if(idx!==null && el){ materiUnlocked[idx]=true; el.open=true; materiRenderDok(idx); }   // hanya materi yang dipilih
  }else{
    document.getElementById('materiIdError').hidden=false;
    document.getElementById('materiIdInput').value='';
    document.getElementById('materiIdInput').focus();
  }
}

function renderMateri(){
  const wrap=document.getElementById('materiWrap');
  wrap.innerHTML='';
  materiData.forEach((m,i)=>{
    const el=document.createElement('details');
    el.className='materi-item';
    // Slot dokumen SENGAJA dikosongkan di sini — tautan file baru ditulis ke DOM
    // oleh materiRenderDok() setelah ID terbukti valid, supaya pengguna yang
    // gagal/belum login tidak bisa melihat URL filenya sama sekali.
    el.innerHTML=`<summary>${m.judul}</summary>
      <div class="materi-body">
        <p class="materi-ringkasan">${m.teks}</p>
        ${m.tool?`<button class="btn ghost materi-btn-mt" onclick="gotoTool('${m.tool[0]}','${m.tool[1]}')">Buka Alat</button>`:''}
        <div class="materi-doc-slot" id="materiDocSlot${i}"></div>
      </div>`;
    el.addEventListener('toggle', function(){
      if(el.open){
        if(!materiUnlocked[i]){
          // Belum terbuka untuk materi ini → tutup lagi dan minta ID lewat form
          el.open=false;
          materiPendingIndex=i;
          materiPendingEl=el;
          bukaMateriIdModal();
        }
      }else{
        // Materi ditutup → kembali terkunci; buka lagi = harus masukkan ID lagi,
        // dan slot dokumen dikosongkan lagi (tautan download ikut hilang dari halaman).
        materiUnlocked[i]=false;
        const slot=document.getElementById('materiDocSlot'+i);
        if(slot) slot.innerHTML='';
      }
    });
    wrap.appendChild(el);
  });
}

/* Ditulis ke DOM hanya sesudah ID/password terbukti valid untuk materi ke-i. */
function materiRenderDok(i){
  const slot=document.getElementById('materiDocSlot'+i);
  if(!slot) return;
  const dok=materiData[i].dokumen;
  slot.innerHTML = dok
    ? `<p class="materi-akses-ok">✅ Akses berhasil.</p>
       <div class="materi-dok">
         <div class="materi-dok-label">Dokumen</div>
         <div class="materi-dok-nama">${dok.nama}</div>
         ${dok.ukuran?`<div class="materi-dok-ukuran">Ukuran: ${dok.ukuran}</div>`:''}
         <a class="btn materi-btn-block materi-dok-btn" href="${dok.file}" download>DOWNLOAD FILE</a>
       </div>`
    : `<p class="materi-akses-ok">✅ Akses berhasil.</p>
       <p class="materi-dok-kosong">Dokumen untuk materi ini belum tersedia.</p>`;
}
renderMateri();

