let lpCurrentIndex = -1;
let lpSeeking = false;

function lpFormatTime(sec){
  if(!isFinite(sec) || sec<0) sec=0;
  const m=Math.floor(sec/60);
  const s=Math.floor(sec%60);
  return String(m).padStart(2,'0')+':'+String(s).padStart(2,'0');
}
function lpQueueIndexes(){
  const arr=[];
  laguHW.forEach((l,i)=>{ if(l.statusAudio==='tersedia') arr.push(i); });
  return arr;
}
function lpLoad(index, autoplay){
  const item = laguHW[index];
  if(!item || !item.audio) return;
  lpCurrentIndex = index;
  lpAudio.pause();
  lpAudio.src = item.audio;
  lpAudio.load();
  lpTitle.textContent = item.judul;
  lpSeek.value = 0;
  lpCurrent.textContent = '00:00';
  lpDuration.textContent = '00:00';
  if(autoplay){ lpSafePlay(); }
  renderLaguHW();
}
/* Putar audio + tampilkan penyebab jika gagal (tidak lagi diam-diam) */
function lpSafePlay(){
  const p = lpAudio.play();
  if(p && p.catch){
    p.catch(err=>{
      if(err && err.name==='NotAllowedError'){
        lpTitle.textContent = (laguHW[lpCurrentIndex]||{}).judul + ' — ketuk tombol Play untuk memulai';
      }else if(err && err.name==='AbortError'){
        /* pergantian lagu cepat: abaikan */
      }else{
        lpDiagnose();
      }
    });
  }
}
/* Cek file audio di server: 404 / bukan MP3 asli / format tidak didukung */
function lpDiagnose(){
  const item = laguHW[lpCurrentIndex];
  if(!item || !item.audio) return;
  const path = item.audio;
  const idx = lpCurrentIndex;
  if(location.protocol!=='http:' && location.protocol!=='https:'){
    lpTitle.textContent = item.judul + ' — ⚠ buka lewat alamat website (GitHub Pages), bukan dari file di HP';
    console.error('[Lagu HW] Halaman dibuka lewat '+location.protocol+' sehingga assets/audio tidak bisa dimuat.');
    renderLaguHW();
    return;
  }
  const tampil = msg=>{
    if(idx!==lpCurrentIndex) return;
    lpTitle.textContent = item.judul + ' — ' + msg;
    renderLaguHW();
    console.error('[Lagu HW] '+item.judul+': '+msg);
  };
  fetch(path,{method:'HEAD',cache:'no-store'}).then(r=>{
    if(r.status===404){ tampil('⚠ file tidak ditemukan: '+path); }
    else if(!r.ok){ tampil('⚠ server membalas HTTP '+r.status+' untuk '+path); }
    else{
      const len = parseInt(r.headers.get('content-length')||'0',10);
      const ct = (r.headers.get('content-type')||'').toLowerCase();
      if((len && len<10000) || ct.indexOf('text/')===0){
        tampil('⚠ '+path+' bukan file MP3 asli (upload tidak lengkap/Git LFS)');
      }else{
        tampil('⚠ file audio tidak bisa diputar di perangkat ini: '+path);
      }
    }
  }).catch(()=>tampil('⚠ gagal memeriksa '+path+' (periksa koneksi)'));
}
lpAudio.addEventListener('error', lpDiagnose);
function lpTogglePlayPause(){
  if(lpCurrentIndex === -1){
    const q = lpQueueIndexes();
    if(q.length) lpLoad(q[0], true);
    return;
  }
  if(lpAudio.paused){ lpSafePlay(); }
  else { lpAudio.pause(); }
}
function lpStopTrack(){
  lpAudio.pause();
  lpAudio.currentTime = 0;
  lpSeek.value = 0;
  lpCurrent.textContent = '00:00';
}
function lpStep(dir){
  const q = lpQueueIndexes();
  if(!q.length) return;
  let pos = q.indexOf(lpCurrentIndex);
  if(pos === -1) pos = 0;
  else pos = (pos + dir + q.length) % q.length;
  lpLoad(q[pos], true);
}
function lpUpdatePlayIcon(){
  const playing = !lpAudio.paused && !lpAudio.ended && lpCurrentIndex !== -1;
  lpIconPlay.style.display = playing ? 'none' : 'block';
  lpIconPause.style.display = playing ? 'block' : 'none';
}
lpPlayPause.addEventListener('click', lpTogglePlayPause);
lpStop.addEventListener('click', lpStopTrack);
lpPrev.addEventListener('click', ()=>lpStep(-1));
lpNext.addEventListener('click', ()=>lpStep(1));
lpAudio.addEventListener('play', lpUpdatePlayIcon);
lpAudio.addEventListener('pause', lpUpdatePlayIcon);
lpAudio.addEventListener('play', ()=>{ renderLaguHW(); });
lpAudio.addEventListener('pause', ()=>{ renderLaguHW(); });
lpAudio.addEventListener('loadedmetadata', ()=>{ lpDuration.textContent = lpFormatTime(lpAudio.duration); });
lpAudio.addEventListener('timeupdate', ()=>{
  if(lpSeeking) return;
  lpCurrent.textContent = lpFormatTime(lpAudio.currentTime);
  if(lpAudio.duration){ lpSeek.value = (lpAudio.currentTime/lpAudio.duration)*100; }
});
lpAudio.addEventListener('ended', ()=>{ lpStep(1); });
lpSeek.addEventListener('input', ()=>{ lpSeeking = true; });
lpSeek.addEventListener('change', ()=>{
  if(lpAudio.duration){ lpAudio.currentTime = (lpSeek.value/100)*lpAudio.duration; }
  lpSeeking = false;
});
lpVolume.addEventListener('input', ()=>{ lpAudio.volume = parseFloat(lpVolume.value); });
lpAudio.volume = parseFloat(lpVolume.value || 1);

function lpPlayFromList(index){
  if(lpCurrentIndex === index){ lpTogglePlayPause(); return; }
  lpLoad(index, true);
}

function renderLaguHW(){
  const wrap=document.getElementById('laguHwWrap');
  wrap.innerHTML='';
  laguHW.forEach((l,i)=>{
    const ada = !!(l.url && l.url.trim());
    const el=document.createElement('div');
    el.className='lagu-hw-item'+(i===lpCurrentIndex?' lagu-hw-item-active':'');

    if(l.statusAudio==='tersedia'){
      const isPlayingThis = i===lpCurrentIndex && !lpAudio.paused;
      const audioHtml = `<button type="button" class="lagu-hw-play" onclick="lpPlayFromList(${i})">${isPlayingThis?'⏸ Sedang Diputar':'▶ Putar'}</button>`;
      el.innerHTML = `<div class="lagu-hw-title">${l.judul}</div>
      <div class="lagu-hw-actions">
        ${audioHtml}
        ${ada
          ? `<a class="lagu-hw-btn" href="${l.url}" target="_blank" rel="noopener noreferrer">Tonton di YouTube</a>`
          : ''}
      </div>`;
    }else{
      el.innerHTML = `<div class="lagu-hw-title">${l.judul}</div>`;
    }
    wrap.appendChild(el);
  });
}
renderLaguHW();

