/* Penyimpanan absen:
   - Jika Firebase aktif: semua perangkat memakai database online yang sama.
   - Jika Firebase belum dikonfigurasi: sementara memakai localStorage seperti versi lama.
*/
const ABSEN_STORAGE_KEY = 'hwAbsenRecords';
const ABSEN_WA_NOMOR = "6281290847354";
let absenRecords = [];
let statusTerpilih = "";

function simpanAbsenKeStorage(){
  if (firebaseAktif) return;
  try{
    localStorage.setItem(ABSEN_STORAGE_KEY, JSON.stringify(absenRecords));
  }catch(e){
    console.warn("localStorage tidak tersedia:", e);
  }
}

function muatAbsenDariLocalStorage(){
  try{
    const tersimpan = localStorage.getItem(ABSEN_STORAGE_KEY);
    if(tersimpan) absenRecords = JSON.parse(tersimpan) || [];
  }catch(e){
    absenRecords = [];
  }
}

function dengarkanAbsenFirebase(){
  if(!firebaseAktif || !absenDbRef) return;

  absenDbRef.on('value', snapshot => {
    const data = snapshot.val() || {};
    absenRecords = Object.entries(data)
      .map(([id, r]) => ({ ...r, _id: id }))
      .sort((a,b) => (a.createdAt || 0) - (b.createdAt || 0));

    renderRekap();
    renderRiwayat();
  }, error => {
    console.error("Gagal membaca database absen:", error);
    showToast("⚠️ Gagal memuat data absen online. Periksa koneksi internet.");
  });
}

async function simpanAbsenOnline(record){
  if(!firebaseAktif || !absenDbRef) return false;

  try{
    const refBaru = absenDbRef.push();
    await refBaru.set(record);
    return true;
  }catch(e){
    console.error("Gagal menyimpan absen:", e);
    showToast("⚠️ Data gagal disimpan. Periksa koneksi internet.");
    return false;
  }
}

/* Ambil jabatan & kelas TERBARU dari anggotaData berdasarkan nama
   (dipakai saat menampilkan Riwayat, supaya update kelas di anggotaData
   langsung terlihat di data yang sudah pernah disimpan). */
function getAnggotaTerkini(nama){
  const m = anggotaData.find(a=>a.nama===nama);
  return m ? {jabatan:m.jabatan, kelas:m.kelas} : null;
}

/* Isi dropdown nama anggota & set tanggal default = hari ini */
function initAbsen(){
  if(!document.getElementById('absenNama')) return;

  const tglInput=document.getElementById('absenTanggal');
  const today=new Date();
  const iso = today.getFullYear()+'-'+String(today.getMonth()+1).padStart(2,'0')+'-'+String(today.getDate()).padStart(2,'0');
  tglInput.value = iso;
}

initAbsen();

if(firebaseAktif){
  dengarkanAbsenFirebase();
}else{
  muatAbsenDariLocalStorage();
}

/* Isi ID, Jabatan/Bidang, dan Kelas otomatis dari anggotaData berdasarkan nama yang dipilih.
   Anggota tidak mengetik ID — ID diambil sistem dari data anggota yang sama dengan Materi HW. */
function isiOtomatisAnggota(){
  const idx=document.getElementById('absenNama').value;
  const idEl=document.getElementById('absenId');
  const jabatanEl=document.getElementById('absenJabatan');
  const kelasEl=document.getElementById('absenKelas');
  if(idx===""){ idEl.value=''; jabatanEl.value=''; kelasEl.value=''; return; }
  const a=anggotaData[idx];
  idEl.value=a.id||'';
  jabatanEl.value=a.jabatan||'';
  kelasEl.value=a.kelas||'';
}

/* ----- Pencarian nama (autocomplete) ----- */
let absenAcIndex=-1;
function absenNormalisasi(s){ return (s||'').toLowerCase().replace(/\s+/g,' ').trim(); }
function absenTutupDaftar(){
  const list=document.getElementById('absenNamaList');
  list.hidden=true; list.innerHTML=''; absenAcIndex=-1;
}
function absenPilihNama(idx){
  const a=anggotaData[idx];
  document.getElementById('absenNamaCari').value=a.nama;
  document.getElementById('absenNama').value=idx;
  absenTutupDaftar();
  isiOtomatisAnggota();
}
function absenCariNama(){
  const input=document.getElementById('absenNamaCari');
  const list=document.getElementById('absenNamaList');
  const q=absenNormalisasi(input.value);
  // Kalau teks diubah setelah memilih, pilihan sebelumnya dibatalkan.
  const terpilih=document.getElementById('absenNama').value;
  if(terpilih!=="" && absenNormalisasi(anggotaData[terpilih].nama)!==q){
    document.getElementById('absenNama').value='';
    isiOtomatisAnggota();
  }
  if(!q){ absenTutupDaftar(); return; }
  const hasil=[];
  anggotaData.forEach((a,i)=>{
    const n=absenNormalisasi(a.nama);
    const pos=n.indexOf(q);
    if(pos===-1) return;
    const awalKata = pos===0 || n.charAt(pos-1)===' ';
    hasil.push({i, skor: awalKata?0:1});
  });
  hasil.sort((x,y)=>x.skor-y.skor || anggotaData[x.i].nama.localeCompare(anggotaData[y.i].nama));
  list.innerHTML='';
  absenAcIndex=-1;
  if(hasil.length===0){
    list.innerHTML='<div class="ac-empty">Nama tidak ditemukan.</div>';
    list.hidden=false;
    return;
  }
  hasil.slice(0,8).forEach(h=>{
    const div=document.createElement('div');
    div.className='ac-item';
    div.textContent=anggotaData[h.i].nama;
    div.dataset.idx=h.i;
    // mousedown (bukan click) supaya terpilih sebelum input kehilangan fokus
    div.addEventListener('mousedown', e=>{ e.preventDefault(); absenPilihNama(h.i); });
    div.addEventListener('touchstart', e=>{ e.preventDefault(); absenPilihNama(h.i); }, {passive:false});
    list.appendChild(div);
  });
  list.hidden=false;
  // Nama diketik lengkap & persis → langsung terpilih
  const persis=hasil.filter(h=>absenNormalisasi(anggotaData[h.i].nama)===q);
  if(persis.length===1 && document.getElementById('absenNama').value===''){ absenPilihNama(persis[0].i); }
}
function absenNamaKey(e){
  const list=document.getElementById('absenNamaList');
  const items=list.querySelectorAll('.ac-item');
  if(e.key==='ArrowDown' && items.length){
    e.preventDefault(); absenAcIndex=(absenAcIndex+1)%items.length;
  }else if(e.key==='ArrowUp' && items.length){
    e.preventDefault(); absenAcIndex=(absenAcIndex-1+items.length)%items.length;
  }else if(e.key==='Enter'){
    e.preventDefault();
    if(items.length){ absenPilihNama(items[absenAcIndex>=0?absenAcIndex:0].dataset.idx); }
    return;
  }else if(e.key==='Escape'){ absenTutupDaftar(); return; }
  else return;
  items.forEach((it,k)=>it.classList.toggle('active',k===absenAcIndex));
}
document.addEventListener('click', e=>{
  if(!e.target.closest('.ac-wrap')) absenTutupDaftar();
});

/* Kosongkan identitas & status supaya siap absen anggota berikutnya (kegiatan & tanggal tetap) */
function absenResetIdentitas(){
  document.getElementById('absenNamaCari').value='';
  document.getElementById('absenNama').value='';
  document.getElementById('absenId').value='';
  document.getElementById('absenJabatan').value='';
  document.getElementById('absenKelas').value='';
  absenTutupDaftar();
  statusTerpilih='';
  document.querySelectorAll('.status-btn').forEach(b=>b.classList.remove('active'));
}

function pilihStatus(status){
  statusTerpilih=status;
  document.querySelectorAll('.status-btn').forEach(b=>b.classList.toggle('active', b.dataset.status===status));
}

function showToast(pesan){
  const t=document.getElementById('toast');
  t.textContent=pesan;
  t.classList.add('show');
  clearTimeout(window._toastTimer);
  window._toastTimer=setTimeout(()=>{ t.classList.remove('show'); }, 2500);
}

/* Kirim data absen langsung ke WhatsApp TANPA menyimpannya ke database website
   (alternatif dari tombol SIMPAN — dipakai kalau memang tidak perlu tercatat di web). */
function kirimAbsenWA(){
  const kegiatan=document.getElementById('absenKegiatan').value;
  const tanggal=document.getElementById('absenTanggal').value;
  const idxNama=document.getElementById('absenNama').value;

  if(!kegiatan){ showToast('⚠️ Pilih kegiatan terlebih dahulu.'); return; }
  if(!tanggal){ showToast('⚠️ Isi tanggal kegiatan terlebih dahulu.'); return; }
  if(idxNama===""){ showToast('⚠️ Pilih nama anggota dari daftar terlebih dahulu.'); return; }
  if(!statusTerpilih){ showToast('⚠️ Pilih status kehadiran terlebih dahulu.'); return; }

  const a=anggotaData[idxNama];
  const jam = new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'});
  window.open("https://wa.me/" + ABSEN_WA_NOMOR + "?text=" + encodeURIComponent(buatPesanAbsenWA(a,kegiatan,tanggal,statusTerpilih,jam)), "_blank");

  absenResetIdentitas();
}

/* Pesan WhatsApp disusun otomatis dari data anggota yang ditemukan lewat nama */
function buatPesanAbsenWA(a,kegiatan,tanggal,status,jam){
  return "*ABSEN HIZBUL WATHAN*\n"
    + "ID: " + (a.id||"-") + "\n"
    + "Nama: " + a.nama + "\n"
    + "Jabatan: " + (a.jabatan||"-") + "\n"
    + "Bidang: " + (a.bidang||"-") + "\n"
    + "Kelas: " + (a.kelas||"-") + "\n"
    + "Kegiatan: " + kegiatan + "\n"
    + "Tanggal: " + formatTanggal(tanggal) + "\n"
    + "Status: " + status + "\n"
    + "Jam: " + jam;
}

async function simpanAbsen(){
  const kegiatan=document.getElementById('absenKegiatan').value;
  const tanggal=document.getElementById('absenTanggal').value;
  const idxNama=document.getElementById('absenNama').value;

  if(!kegiatan){ showToast('⚠️ Pilih kegiatan terlebih dahulu.'); return; }
  if(!tanggal){ showToast('⚠️ Isi tanggal kegiatan terlebih dahulu.'); return; }
  if(idxNama===""){ showToast('⚠️ Pilih nama anggota dari daftar terlebih dahulu.'); return; }
  if(!statusTerpilih){ showToast('⚠️ Pilih status kehadiran terlebih dahulu.'); return; }

  const a=anggotaData[idxNama];
  const recordBaru = {
    id:a.id||'',
    nama:a.nama,
    jabatan:a.jabatan||'',
    bidang:a.bidang||'',
    kelas:a.kelas||'',
    kegiatan,
    tanggal,
    status:statusTerpilih,
    jam: new Date().toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'}),
    createdAt: Date.now()
  };

  if(firebaseAktif){
    const berhasil = await simpanAbsenOnline(recordBaru);
    if(!berhasil) return false;
  }else{
    absenRecords.push(recordBaru);
    simpanAbsenKeStorage();
  }

  absenResetIdentitas();

  showToast('✅ Absensi berhasil disimpan.');
  renderRekap();
  renderRiwayat();
  return recordBaru;
}

/* Alur utama: SIMPAN ke database → KIRIM WhatsApp dengan data yang sama.
   Jendela WhatsApp dibuka lebih dulu (saat tombol ditekan) agar tidak diblokir browser,
   lalu diarahkan ke pesan setelah data berhasil tersimpan. */
async function simpanDanKirimWA(){
  const kegiatan=document.getElementById('absenKegiatan').value;
  const tanggal=document.getElementById('absenTanggal').value;
  const idxNama=document.getElementById('absenNama').value;
  if(!kegiatan){ showToast('⚠️ Pilih kegiatan terlebih dahulu.'); return; }
  if(!tanggal){ showToast('⚠️ Isi tanggal kegiatan terlebih dahulu.'); return; }
  if(idxNama===""){ showToast('⚠️ Pilih nama anggota dari daftar terlebih dahulu.'); return; }
  if(!statusTerpilih){ showToast('⚠️ Pilih status kehadiran terlebih dahulu.'); return; }

  const a=anggotaData[idxNama];
  const status=statusTerpilih;
  const waWin=window.open('about:blank','_blank');
  const record=await simpanAbsen();
  if(!record){ if(waWin) waWin.close(); return; }
  const url="https://wa.me/"+ABSEN_WA_NOMOR+"?text="+encodeURIComponent(buatPesanAbsenWA(a,kegiatan,tanggal,status,record.jam));
  if(waWin){ waWin.location.href=url; }
  else{ window.location.href=url; }
}

function recordsTerfilter(){
  const kegiatan=document.getElementById('absenKegiatan').value;
  const tanggal=document.getElementById('absenTanggal').value;
  return absenRecords.filter(r => (!kegiatan || r.kegiatan===kegiatan) && (!tanggal || r.tanggal===tanggal));
}

function renderRekap(){
  const data=recordsTerfilter();
  document.getElementById('rekapTotal').textContent = anggotaData.length;
  document.getElementById('rekapHadir').textContent = data.filter(r=>r.status==='Hadir').length;
  document.getElementById('rekapIzin').textContent = data.filter(r=>r.status==='Izin').length;
  document.getElementById('rekapSakit').textContent = data.filter(r=>r.status==='Sakit').length;
  document.getElementById('rekapAlpa').textContent = data.filter(r=>r.status==='Alpa').length;
}

function renderRiwayat(){
  const wrap=document.getElementById('riwayatList');
  const data=recordsTerfilter();
  if(data.length===0){
    wrap.innerHTML='<div class="empty-note">Belum ada data absen untuk kegiatan &amp; tanggal ini.</div>';
    return;
  }
  const statusClassMap={Hadir:'rs-hadir',Izin:'rs-izin',Sakit:'rs-sakit',Alpa:'rs-alpa'};
  const statusEmojiMap={Hadir:'🟢',Izin:'🟡',Sakit:'🔵',Alpa:'🔴'};
  wrap.innerHTML='';
  data.slice().reverse().forEach(r=>{
    const terkini = getAnggotaTerkini(r.nama);
    const kelasTampil = terkini ? terkini.kelas : r.kelas;
    const el=document.createElement('div');
    el.className='riwayat-row';
    el.innerHTML=`<span class="rn">${r.nama} <span style="color:var(--muted);font-weight:500;">· ${kelasTampil} · ${r.jam}</span></span>
      <span class="rs ${statusClassMap[r.status]}">${statusEmojiMap[r.status]} ${r.status}</span>`;
    wrap.appendChild(el);
  });
}

renderRekap();
renderRiwayat();

