/* Kirim hasil quiz (nama + skor + kategori) ke WhatsApp admin.
   Catatan: website statis tidak bisa mengirim WhatsApp otomatis tanpa
   interaksi pengguna, jadi ini membuka WhatsApp dengan pesan yang sudah
   terisi — peserta tinggal menekan tombol kirim di WhatsApp. */
function qzKirimWAIndividu(){
  const elapsed = Date.now() - qzIndividu.startedAt;
  const cat = qzCategory(qzIndividu.score);
  const pesan = "*HASIL QUIZ DPDP CHARACTER CHALLENGE*\n"
    + "Mode: Individu\n"
    + "Nama: " + qzIndividu.name + "\n"
    + "Skor: " + qzIndividu.score + "/" + QZ_MAX + "\n"
    + "Benar: " + qzIndividu.correct + " | Salah: " + qzIndividu.wrong + "\n"
    + "Akurasi: " + Math.round((qzIndividu.correct/QZ_INDIVIDU.length)*100) + "%\n"
    + "Waktu: " + qzFormatTime(elapsed) + "\n"
    + "Kategori: " + cat.title;
  window.open("https://wa.me/" + QZ_WA_NOMOR + "?text=" + encodeURIComponent(pesan), "_blank");
}
function qzKirimWAKelompok(){
  const elapsed = Date.now() - qzKelompok.startedAt;
  const cat = qzCategory(qzKelompok.score);
  const pesan = "*HASIL QUIZ DPDP CHARACTER CHALLENGE*\n"
    + "Mode: Kelompok\n"
    + "Kelompok: " + qzKelompok.groupName + "\n"
    + (qzKelompok.members.length ? ("Anggota: " + qzKelompok.members.join(", ") + "\n") : "")
    + "Skor: " + qzKelompok.score + "/" + QZ_MAX + "\n"
    + "Benar: " + qzKelompok.correct + " | Salah: " + qzKelompok.wrong + "\n"
    + "Akurasi: " + Math.round((qzKelompok.correct/QZ_KELOMPOK.length)*100) + "%\n"
    + "Waktu: " + qzFormatTime(elapsed) + "\n"
    + "Kategori: " + cat.title;
  window.open("https://wa.me/" + QZ_WA_NOMOR + "?text=" + encodeURIComponent(pesan), "_blank");
}

