/* ========================================
   ANTI TINGGALKAN HALAMAN — Quiz DPDP
   Kalau peserta pindah tab/aplikasi (visibilitychange) atau jendela
   kehilangan fokus (blur) SAAT sedang mengerjakan quiz, mainkan bunyi
   peringatan lalu kunci quiz dengan overlay sampai mereka menekan
   "Kembali ke Menu Quiz".
   ======================================== */
let qzActiveMode = null;       // null | 'individu' | 'kelompok' — hanya terisi SAAT sedang mengerjakan soal
let qzPelanggaranTerjadi = false;

function qzTandaiMulai(mode){
  qzActiveMode = mode;
  qzPelanggaranTerjadi = false;
}
function qzTandaiSelesai(){
  qzActiveMode = null;
}

/* Aktifkan/"unlock" audio SAAT peserta menekan tombol Mulai (ini masih
   dianggap interaksi pengguna oleh browser), supaya nanti bunyi peringatan
   yang dipicu otomatis (tanpa klik, saat blur/visibilitychange) tetap bisa
   diputar meski browser biasanya memblokir audio otomatis. */
function qzUnlockAudio(){
  try{
    if(!audioCtx) audioCtx = new (window.AudioContext||window.webkitAudioContext)();
    if(audioCtx.state === 'suspended') audioCtx.resume();
  }catch(e){ /* abaikan kalau Web Audio tidak didukung */ }
}

/* Bunyi beep peringatan (bukan musik) — pakai audioCtx yang sama dengan Morse,
   tapi nada & fungsi terpisah supaya suara Morse tidak ikut berubah. */
function qzAlarmBeep(freq, duration){
  return new Promise(resolve=>{
    try{
      if(!audioCtx) audioCtx = new (window.AudioContext||window.webkitAudioContext)();
      const osc=audioCtx.createOscillator();
      const gain=audioCtx.createGain();
      osc.type='square';
      osc.frequency.value=freq;
      osc.connect(gain); gain.connect(audioCtx.destination);
      gain.gain.value=0.35;
      osc.start();
      setTimeout(()=>{ try{osc.stop();}catch(e){} resolve(); }, duration);
    }catch(e){ resolve(); }
  });
}
async function qzMainkanBunyiPeringatan(){
  await qzAlarmBeep(880,180);
  await new Promise(r=>setTimeout(r,90));
  await qzAlarmBeep(880,180);
  await new Promise(r=>setTimeout(r,90));
  await qzAlarmBeep(880,320);
}

function qzTriggerPelanggaran(){
  if(!qzActiveMode || qzPelanggaranTerjadi) return;
  qzPelanggaranTerjadi = true;

  // Kunci Quiz: matikan semua tombol pilihan jawaban yang sedang tampil
  document.querySelectorAll('#quizdpdp-individu-quiz .qz-opt, #quizdpdp-kelompok-quiz .qz-opt')
    .forEach(function(b){ b.disabled = true; });

  qzMainkanBunyiPeringatan();
  document.getElementById('qzWarningOverlay').classList.add('show');
}
function qzTutupPeringatanKeMenu(){
  document.getElementById('qzWarningOverlay').classList.remove('show');
  qzTandaiSelesai();
  qzResetIndividuForm();
  qzResetKelompokForm();
  switchSub('quizdpdp','menu');
}

document.addEventListener('visibilitychange', function(){
  if(document.hidden) qzTriggerPelanggaran();
});
window.addEventListener('blur', function(){
  qzTriggerPelanggaran();
});

